267	     * before the owner is persisted, so it reflects the owners present at creation time.
268	     */
269	    private int countNamesakes(Owner owner) {
270	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
271	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
272	        return (int) ownerRepository.findAll().stream()
273	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
274	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
