278	    /**
279	     * Reconcile the owner's household. Owners are in the same household when their last name and
280	     * address match (compared case-insensitively with collapsed whitespace). When another owner
281	     * already lives there, the create is rejected with {@link DuplicateHouseholdException} unless
282	     * {@code sharesHousehold} is set, in which case the new owner and every existing member are
283	     * given the same stable shared {@code householdId}.
284	     */
285	    private void assignHousehold(Owner owner, boolean sharesHousehold) {
286	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
